public int[] DailyTemperatures(int[] t) {
    var ans = new int[t.Length];
    for (int i = 0; i < t.Length; i++)
        for (int j = i + 1; j < t.Length; j++)
            if (t[j] > t[i]) { ans[i] = j - i; break; }   // нашли — дальше не ищем
    return ans;
}

