public int LargestRectangleArea(int[] h) {
    var stack = new Stack<int>(); // индексы, высоты возрастают
    int best = 0;
    for (int i = 0; i <= h.Length; i++) {
        int cur = i == h.Length ? 0 : h[i];             // стоппер высоты 0
        while (stack.Count > 0 && h[stack.Peek()] >= cur) {
            int height = h[stack.Pop()];                // i — его правая граница
            int left = stack.Count == 0 ? 0 : stack.Peek() + 1;   // а это левая
            best = Math.Max(best, height * (i - left));
        }
        stack.Push(i);
    }
    return best;
}

