// самая большая свободная площадка на тайловой карте
int LargestFreeArea(bool[,] free) {
    int rows = free.GetLength(0), cols = free.GetLength(1), best = 0;
    var heights = new int[cols];
    for (int r = 0; r < rows; r++) {
        for (int c = 0; c < cols; c++)
            heights[c] = free[r, c] ? heights[c] + 1 : 0;   // свободных клеток подряд вверх
        best = Math.Max(best, LargestRectangleArea(heights));
    }
    return best;
}
